"""Circuit breaker state machine."""
import time

from .storage import CLOSED, HALF_OPEN, OPEN


class CallNotPermittedError(RuntimeError):
    pass


class CircuitBreaker:
    def __init__(self, failure_threshold=3, half_open_successes=2,
                 cool_off_seconds=1.0, policy=None, clock=time.monotonic):
        self.failure_threshold = failure_threshold
        self.half_open_successes = half_open_successes
        self.cool_off_seconds = cool_off_seconds
        self.policy = policy
        self._clock = clock
        from .storage import InMemoryStorage
        self.storage = InMemoryStorage()
        self.opened_at = None

    @property
    def state(self):
        return self.storage.state

    def allow_request(self):
        now = self._clock()
        if self.storage.state == OPEN:
            if now - self.opened_at >= self.cool_off_seconds:
                self.storage.state = HALF_OPEN
                self.storage.success_streak = 0
            else:
                raise CallNotPermittedError("circuit is OPEN")
        return True

    def call(self, fn, *args, **kwargs):
        self.allow_request()
        try:
            result = fn(*args, **kwargs)
        except Exception:
            self.record_failure()
            raise
        self.record_success()
        return result

    def record_failure(self):
        if self.storage.state == HALF_OPEN:
            self.trip_open()
            return
        self.storage.failure_count += 1
        self.storage.success_streak = 0
        if self.storage.failure_count >= self.failure_threshold:
            self.trip_open()

    def record_success(self):
        if self.storage.state == HALF_OPEN:
            # BENCHMARK BUG: one success is enough to close the breaker and
            # counters are never cleared on transition.
            self.storage.state = CLOSED
            return
        self.storage.success_streak += 1

    def trip_open(self):
        self.storage.state = OPEN
        self.opened_at = self._clock()
        self.storage.reset()

