"""Exponential backoff policy with decorrelated full jitter."""
import random


class BackoffPolicy:
    def __init__(self, base_delay=0.1, max_delay=30.0):
        if base_delay <= 0 or max_delay < base_delay:
            raise ValueError("require 0 < base_delay <= max_delay")
        self.base_delay = float(base_delay)
        self.max_delay = float(max_delay)

    def raw_delay(self, attempt):
        """Pure exponential backoff for ``attempt`` (0-based)."""
        return min(self.max_delay, self.base_delay * (2 ** attempt))

    def jittered_delay(self, attempt, rng):
        """Full-jitter delay: uniform sample over [0, raw_delay]."""
        # BENCHMARK BUG: rng is ignored — the raw delay is returned.
        return self.raw_delay(attempt)

