"""Breaker state storage (counters + current state)."""

CLOSED = "CLOSED"
OPEN = "OPEN"
HALF_OPEN = "HALF_OPEN"


class InMemoryStorage:
    def __init__(self):
        self.state = CLOSED
        self.failure_count = 0
        self.success_streak = 0

    def reset(self):
        self.failure_count = 0
        self.success_streak = 0

    def snapshot(self):
        return {
            "state": self.state,
            "failure_count": self.failure_count,
            "success_streak": self.success_streak,
        }
